'use strict';

const {
  CAMPAIGN_ID,
  DOMAIN_SHARDS,
} = require('./eppp_distractor_halving_campaign_manifest.cjs');
const currentBank = require('../test_prep/eppp_native_items.json');

const shardId = 'eppp-distractor-halving-revisions-b';
const reviewedAt = '2026-07-25';
const assignedDomains = Object.freeze(['assessment', 'biological', 'cognitive-affective']);
const assignedItems = Object.freeze(assignedDomains.flatMap((domainId) => DOMAIN_SHARDS[domainId]));
const assignedIds = Object.freeze(assignedItems.map((item) => item.id));
const campaignById = new Map(assignedItems.map((item) => [item.id, item]));
const currentById = new Map(currentBank.map((item) => [item.id, item]));

function invariant(condition, message) {
  if (!condition) throw new Error(shardId + ': ' + message);
}

function normalize(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function wordCount(value) {
  return String(value || '').trim().split(/\s+/).filter(Boolean).length;
}

function buildRevision(id, patch) {
  const campaign = campaignById.get(id);
  const current = currentById.get(id);
  invariant(campaign, 'unexpected authored ID ' + id);
  invariant(current, 'live item does not resolve for ' + id);
  invariant(Array.isArray(patch.choices) && patch.choices.length === 4, id + ' must author four choices');
  const liveWaveNumber = Number(String(current.wordingReviewWave || '').match(/wave-(\d+)$/)?.[1] || 0);
  const laterNativeWave = liveWaveNumber > 23;
  invariant(
    laterNativeWave || patch.choices[campaign.expectedAnswerIndex] === current.choices[current.answerIndex],
    id + ' must preserve the exact keyed-choice wording',
  );
  if (laterNativeWave) patch.choices[campaign.expectedAnswerIndex] = current.choices[current.answerIndex];
  invariant(Array.isArray(patch.distractorDesign) && patch.distractorDesign.length === 3, id + ' must have three distractor labels');
  invariant(new Set(patch.distractorDesign).size === 3, id + ' distractor labels must be distinct');
  invariant(patch.editorialNote && patch.editorialNote.length >= 80, id + ' needs a substantive editorial note');
  invariant(['application', 'analysis'].includes(patch.cognitiveProcess), id + ' must use application or analysis');

  const incorrectIndexes = [0, 1, 2, 3].filter((optionIndex) => optionIndex !== campaign.expectedAnswerIndex);
  invariant(
    Object.keys(patch.incorrectFeedback).map(Number).sort().join(',') === incorrectIndexes.join(','),
    id + ' must author feedback for exactly the three distractors',
  );
  const choiceRationales = patch.choices.map((choice, optionIndex) => (
    optionIndex === campaign.expectedAnswerIndex ? patch.rationale : patch.incorrectFeedback[optionIndex]
  ));
  const normalizedKey = normalize(patch.choices[campaign.expectedAnswerIndex]);
  for (const optionIndex of incorrectIndexes) {
    const feedback = choiceRationales[optionIndex];
    invariant(feedback.length >= 100, id + ' option ' + optionIndex + ' feedback is too short');
    invariant(wordCount(feedback) >= 16, id + ' option ' + optionIndex + ' feedback needs at least 16 words');
    invariant(!/\b(?:is not best because|does not meet the defining condition or distinction|the supported response is|makes an absolute or unconditional claim|does not represent the best available answer)\b/i.test(feedback), id + ' option ' + optionIndex + ' uses stock rejection language');
    invariant(!normalize(feedback).includes(normalizedKey), id + ' option ' + optionIndex + ' echoes the full key');
  }

  const {
    incorrectFeedback,
    ...authoredFields
  } = patch;
  return Object.freeze({
    expectedAnswerIndex: campaign.expectedAnswerIndex,
    contentSha256: campaign.contentSha256,
    expectedWarningFamilies: campaign.expectedWarningFamilies,
    ...authoredFields,
    choiceRationales: Object.freeze(choiceRationales),
    distractorDesign: Object.freeze([...patch.distractorDesign]),
  });
}

